<script setup lang="ts">
import { computed, onScopeDispose, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, asApiError, type ApiError } from '../api/client';
import { useRemote } from '../composables/useRemote';
import { contract, parsePaymentFilters, paymentQuery, type Mandate, type MandateUpdate } from '../domain/m3';
import { formatFen, shanghaiTime } from '../domain/m1';
import { useSessionStore } from '../stores/session';
import ErrorPanel from '../components/ErrorPanel.vue';
import PagePagination from '../components/PagePagination.vue';
import StatusBadge from '../components/StatusBadge.vue';
import PaymentNavigation from '../components/PaymentNavigation.vue';
const route=useRoute();const router=useRouter();const session=useSessionStore();const filters=computed(()=>parsePaymentFilters(route.query));const page=useRemote(()=>api.listMandates(filters.value.limit,filters.value.offset));
const selected=ref<Mandate|null>(null);const draft=ref<MandateUpdate|null>(null);const confirm=ref(false);const pending=ref(false);const error=ref<ApiError|null>(null);const notice=ref('');let revision=0;onScopeDispose(()=>revision++);
const statusNames:Record<string,string>={PENDING:'待模拟签约',ACTIVE:'Mock 签约已生效',EXPIRED:'Mock 签约已失效',REVOKED:'Mock 签约已撤销'};
watch(()=>route.fullPath,()=>{revision++;selected.value=null;draft.value=null;confirm.value=false;pending.value=false;error.value=null;notice.value='';void page.load();},{immediate:true,flush:'sync'});
function edit(value:Mandate){selected.value=value;draft.value={status:value.status==='PENDING'?'ACTIVE':value.status,maxSingleFen:value.maxSingleFen,version:value.version};confirm.value=false;error.value=null;}
function review(){if(!pending.value&&session.can('payments.manage')&&draft.value&&contract<MandateUpdate>('M3MandateUpdate')(draft.value))confirm.value=true;}
async function save(){if(pending.value||!confirm.value||!session.can('payments.manage')||!selected.value||!draft.value)return;const current=revision;const id=selected.value.id;pending.value=true;error.value=null;try{const value=await api.updateMandate(id,{...draft.value});if(current!==revision)return;confirm.value=false;selected.value=null;draft.value=null;notice.value=statusNames[value.status]!;await page.load();}catch(cause){if(current===revision)error.value=asApiError(cause);}finally{if(current===revision)pending.value=false;}}
function paginate(offset:number,limit:number){void router.push({path:'/payments/mandates',query:paymentQuery({limit,offset},false)});}
</script>
<template><div><div class="page-heading"><div><p class="eyebrow">支付中心 / 签约</p><h1>Mock 免密签约</h1><p class="muted">合成采购账号 · Mock / 待授权</p></div><el-button :loading="page.loading.value" :disabled="pending" @click="page.load">刷新签约状态</el-button></div><PaymentNavigation /><p class="scope-hint">本页仅切换合成签约状态。有效期由服务端生成，无真实协议、账号密码或支付凭据。撤销停止新自动发起，已在途只查单。</p><p v-if="notice" class="success-note" role="status">{{ notice }}</p><section class="panel table-panel" :aria-busy="page.loading.value"><div v-if="page.loading.value" class="data-state" role="status"><el-skeleton :rows="4" animated /><p>正在读取 Mock 签约…</p></div><ErrorPanel v-else-if="page.error.value" :error="page.error.value" title="签约记录读取失败"><el-button @click="page.load">重试</el-button></ErrorPanel><div v-else-if="page.data.value&&!page.data.value.items.length" class="data-state"><h2>暂无可见 Mock 签约记录</h2><p>尚未签约时，自动付款不会创建假支付流水。</p></div><div v-else-if="page.data.value" class="table-scroll"><table class="data-table"><thead><tr><th>合成采购账号</th><th>状态 / 上限</th><th>有效期 / 核验时间（上海）</th><th>版本 / 操作</th></tr></thead><tbody><tr v-for="mandate in page.data.value.items" :key="mandate.id"><td><strong>{{ mandate.supplierAccountName }}</strong><small class="mono">{{ mandate.supplierAccountId }}</small></td><td><StatusBadge :status="mandate.status" /><small>{{ statusNames[mandate.status] }} · {{ formatFen(mandate.maxSingleFen) }} CNY / 笔</small></td><td class="time-cell">{{ mandate.expiresAt?shanghaiTime(mandate.expiresAt):'无有效期 · 尚未生效' }}<small>核验 {{ mandate.lastVerifiedAt?shanghaiTime(mandate.lastVerifiedAt):'尚未核验' }}</small></td><td>版本 {{ mandate.version }}<el-button v-if="session.can('payments.manage')" data-testid="edit-mandate" text type="primary" :disabled="pending" @click="edit(mandate)">修改 Mock 状态</el-button></td></tr></tbody></table></div><PagePagination v-if="page.data.value" :total="page.data.value.total" :limit="filters.limit" :offset="filters.offset" :loading="page.loading.value" @change="paginate" /></section><section v-if="selected&&draft&&session.can('payments.manage')" class="panel editor-panel"><h2>{{ selected.supplierAccountName }} · 修改合成签约</h2><form data-testid="mandate-form" class="policy-form" @submit.prevent="review"><label>Mock 状态<select v-model="draft.status" name="mandateStatus" :disabled="pending"><option value="ACTIVE">ACTIVE · 生效</option><option value="EXPIRED">EXPIRED · 失效</option><option value="REVOKED">REVOKED · 撤销</option></select></label><label>单笔 Mock 签约上限（分）<input v-model.number="draft.maxSingleFen" name="mandateMaxSingleFen" type="number" min="0" max="1000000000000" step="1" required :disabled="pending" /></label><el-button native-type="submit" :disabled="pending||!contract<MandateUpdate>('M3MandateUpdate')(draft)">审核修改（版本 {{ draft.version }}）</el-button></form><ErrorPanel v-if="error&&!confirm" :error="error" /></section><el-dialog v-model="confirm" title="确认修改 Mock 签约" width="500px" :close-on-click-modal="false" :close-on-press-escape="!pending" :show-close="!pending"><p>{{ selected?.supplierAccountName }} · {{ draft?.status }}</p><p class="help-text">Mock 生效仅允许通过策略与风控检查的合成付款；失效或撤销将阻止新的自动付款。已在途付款保持只读查单，不重新付款。</p><ErrorPanel v-if="error" :error="error"><el-button v-if="error.status===409" :disabled="pending" @click="confirm=false;selected=null;draft=null;page.load()">刷新最新版本</el-button></ErrorPanel><template #footer><el-button :disabled="pending" @click="confirm=false">取消</el-button><el-button data-testid="confirm-mandate" type="primary" :loading="pending" :disabled="pending" @click="save">确认修改</el-button></template></el-dialog></div></template>
